export const BODY: string = "\n<p>وجدت اللون المثالي في صورة أو لقطة شاشة، والآن تحتاج رمزه. التخمين يضيع الوقت، ولون شبه متطابق يبدو سيئًا بجانب الأصل.</p>\n<p>هذا الدليل يأخذك خطوة بخطوة لاختيار لون من صورة في أربع خطوات عملية: سترفع الصورة وتصوّب بالعدسة وتحفظ اللون وتصدّره لمشروعك.</p>\n<p>العملية كلها تستغرق أقل من دقيقة بمجرد أن تعرفها. لا برنامج للتثبيت ولا حساب للإنشاء ولا ملف يُرفع إلى أي خادم.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج الصورة التي تحتوي اللون: صورة أو ملف شعار أو لقطة شاشة أو نموذج تصميم تعمل، بصيغة JPG أو PNG أو WebP أو GIF.</p>\n<p>يمكن أن يزن الملف حتى 20 MB، ما يغطي بسهولة صور الهاتف ولقطات الشاشة عالية الدقة: إذا كان ملفك أكبر، اضغطه أولًا أو التقط لقطة للمنطقة. وتحتاج أيضًا متصفحًا: تعمل الأداة في Chrome وSafari وFirefox وEdge، على الحاسوب والهاتف، دون أي إضافة أو ملحق.</p>\n<p>وأخيرًا، اعرف أين اللون داخل الصورة: فكرة تقريبية عن موضعه توفر وقتًا، خصوصًا في صورة مزدحمة بكثير من الدرجات المتشابهة.</p>\n<h2 id=\"step-1-upload-or-paste\">الخطوة 1: ارفع الصورة أو الصق لقطة شاشة</h2>\n<p>افتح <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a> واسحب صورتك إلى منطقة الرفع. ويمكنك أيضًا النقر على المنطقة لاختيار ملف من جهازك.</p>\n<p>وإذا كان اللون على شاشتك الآن، التقط لقطة شاشة والصقها بـCtrl+V على Windows أو Cmd+V على Mac: تقبل الأداة صور الحافظة مباشرة. وتظهر الصورة في المنتقي فور تحميلها: يُعرض لون فورًا، مأخوذ من وسط الصورة، لتعرف أن الأداة جاهزة.</p>\n<p>وإذا رفعت الملف الخطأ، بدّل إلى صورة أخرى من الأداة: تُحفظ عيناتك السابقة، فتستطيع متابعة جمع الألوان عبر صور عدة إن احتجت.</p>\n<h2 id=\"step-2-aim-with-the-loupe\">الخطوة 2: صوّب بعدسة التكبير</h2>\n<p>حرّك المؤشر فوق الصورة وراقب العدسة المكبرة 11 في 11: تُظهر شبكة مكبرة للبكسلات حول مؤشرك، مع البكسل المستهدف في الوسط.</p>\n<p>تباطأ وأنت تقترب من اللون الذي تبحث عنه: تتيح لك العدسة رؤية الفرق بين وسط صلب لشكل وحافته الممزوجة. وصوّب إلى وسط منطقة مسطحة: زر أو جدار أو كتلة لون صلبة في الوسط وتمتزج عند الحواف، فالوسط يعطي القيمة الحقيقية.</p>\n<p>راجع فاحص البكسلات وأنت تتحرك: يُظهر الإحداثيات الدقيقة والقيم الحية لـHEX وRGB وHSL وCMYK للبكسل تحت مؤشرك.</p>\n<h2 id=\"step-3-click-to-save-the-swatch\">الخطوة 3: انقر لحفظ العينة</h2>\n<p>عندما تُظهر العدسة البكسل الصحيح، انقر: ينضم اللون إلى صينية عيناتك المختارة وتُعرض رموزه للنسخ.</p>\n<p>انقر رمز HEX لنسخه: HEX هو الصيغة التي يحتاجها معظم الناس، لأنه يُلصق مباشرة في CSS وFigma وCanva ومعظم أدوات التصميم. واجمع كل الألوان التي تحتاجها قبل مغادرة الصفحة: مجموعة كاملة قد تشمل اللون الرئيسي وتمييزًا وخلفية ولون نص من نفس الصورة.</p>\n<p>وإذا بدت عينتان متطابقتين، لن تحفظ الأداة مكررًا: النقر مرتين على نفس قيمة HEX يترك لك إدخالًا واحدًا نظيفًا، لا اثنين.</p>\n<h2 id=\"step-4-export-or-copy\">الخطوة 4: صدّر CSS أو انسخ الرموز</h2>\n<p>عندما تكتمل عيناتك، انقر تصدير CSS: تنزّل الأداة ملفًا بألوانك كخصائص CSS مخصصة، جاهزة للصق في ورقة أنماط.</p>\n<p>وإذا احتجت لونًا واحدًا فقط، انسخ رمز HEX مباشرة من الفاحص: هذا أسرع من تنزيل ملف لقيمة واحدة. ولأعمال الطباعة، دوّن قيم CMYK المعروضة لكل اختيار: إنها تقريب أولي، مفيد لإبلاغ مصمم طباعة قبل تحويل مناسب.</p>\n<p>اختبر اللون في مشروعك فورًا: الصق الرمز وراجعه بجانب الصورة الأصلية وتأكد من تطابقه قبل بناء أي شيء عليه.</p>\n<h2 id=\"picking-from-a-photo\">كيف تأخذ لونًا من صورة</h2>\n<p>الصور تحتاج لمسة مختلفة قليلًا عن الرسوم المسطحة: ضجيج الكاميرا وضغط JPEG يجعلان البكسلات المجاورة تختلف، فنقرة واحدة نادرًا ما تروي القصة كاملة.</p>\n<p>عيّن نفس المنطقة ثلاث أو أربع مرات، متحركًا بكسلًا أو اثنين في كل مرة: إذا تطابقت الرموز في أول خمسة أرقام، وجدت اللون الحقيقي. واختر أكبر منطقة مسطحة تستطيع إيجادها: سماء صافية أو باب مطلي أو قميص صلب يعطي قراءة أكثر استقرارًا بكثير من سطح منقوش.</p>\n<p>ابتعد عن التوهجات الساطعة والظلال العميقة: تلك المناطق تفقد معلومات اللون، والرمز الذي تقرأه هناك غالبًا أبيض أو أسود أو رمادي فقط.</p>\n<h2 id=\"picking-from-a-logo\">كيف تأخذ لونًا من شعار</h2>\n<p>الشعارات تتطلب دقة، لأن لون علامة ينحرف برقم واحد ما زال يبدو سيئًا: ابدأ بأعلى ملف شعار جودة لديك، ويفضل PNG.</p>\n<p>تحفظ ملفات PNG الألوان الدقيقة، فالقراءة موثوقة. وشعارات JPEG تحمل ضجيج ضغط، قد يغيّر الرقم الأخير من رمز HEX. وعيّن وسط أكبر شكل مسطح في الشعار: وسط حرف أو كتلة صلب، بينما الحواف تمتزج مع الخلفية.</p>\n<p>تحقق من النتيجة بوضع اللون المختار بجانب الشعار على نفس الشاشة: إذا تطابقا، فلديك لون العلامة. وإذا لم يتطابقا، جرّب بكسلًا أو اثنين نحو الداخل.</p>\n<h2 id=\"picking-from-a-screenshot\">كيف تأخذ لونًا من لقطة شاشة</h2>\n<p>لقطات الشاشة هي أسرع مصدر لألوان الواجهة: التقط الشاشة والصقها بـCtrl+V وعيّن الزر أو الترويسة أو الخلفية مباشرة.</p>\n<p>استخدم العدسة بعناية في اللقطات: عناصر الواجهة لها حواف منعّمة، فبكسلات الحافة مزيج من العنصر والخلفية. ولألوان النص، عيّن أسمك جزء من حرف، مثل وسط ضربة عريضة: النص الرفيع معظمه بكسلات حافة، تُقرأ كمزيج.</p>\n<p>دوّن إحداثيات البكسل وأنت تعمل: إذا شكك زميل في قيمة، تتيح الإحداثيات لكما العودة إلى نفس النقطة الدقيقة وتأكيدها.</p>\n<h2 id=\"picking-on-a-phone\">كيف تأخذ لونًا على هاتف أو جهاز لوحي</h2>\n<p>على شاشة لمس تلمس بدل النقر، وتنطبق نفس أدوات العدسة والعينات: ارفع الصورة من معرضك أو الصق لقطة شاشة.</p>\n<p>طرف إصبعك يغطي بكسلات كثيرة، فكبّر الصورة أولًا: صورة أكبر تعطيك هدفًا أكبر وفرصة أفضل لإصابة البكسل الصحيح. واستخدم العدسة للتأكيد قبل اللمس: تُظهر ما تحت إصبعك، وهو ما لا تستطيع رؤيته بينما إصبعك على الشاشة.</p>\n<p>وللون يجب أن يكون دقيقًا، مثل لون علامة، قم بالتحقق الأخير على حاسوب: نقرة فأرة على بكسل أكثر موثوقية من لمسة بطرف إصبع.</p>\n<h2 id=\"troubleshooting-wrong-colors\">حل المشاكل: عندما يبدو اللون خطأ</h2>\n<p>إذا بدا اللون المختار فاتحًا جدًا أو داكنًا جدًا، فغالبًا عيّنت توهجًا أو ظلًا: تحرك نحو وسط الشكل وحاول مجددًا.</p>\n<p>وإذا بدا اللون ضبابيًا، فغالبًا أخذت حافة منعّمة: تحرك بكسلًا أو اثنين نحو الداخل، حيث اللون صلب وغير ممزوج. وإذا تغيّر رمز HEX في كل مرة تنقر فيها، فالمنطقة بها ضجيج: عيّن عدة بكسلات قريبة واستخدم القيمة التي تظهر أكثر.</p>\n<p>وإذا بدا اللون جيدًا في المنتقي لكنه سيئ في أداة تصميمك، راجع الرمز الذي لصقته: رقم مفقود أو حرف متغير هو السبب المعتاد، لا المنتقي.</p>\n<h2 id=\"using-the-color-in-your-project\">كيف تستخدم اللون المختار في مشروعك</h2>\n<p>في موقع، الصق رمز HEX في CSS أو استخدم الخصائص المخصصة المصدّرة: نهج المتغيرات يبقي ألوانك متسقة عبر الموقع كله.</p>\n<p>في Figma أو Canva أو Photoshop، الصق رمز HEX في حقل اللون: كل أدوات التصميم الرئيسية تقبل HEX، فتنتقل القيمة دون تحويل. ولعرض تقديمي أو مستند، استخدم قيم RGB: أدوات المكتب غالبًا تُظهر اللون كثلاثة أرقام، وقراءة RGB تطابق تلك الصيغة بالضبط.</p>\n<p>وللطباعة، ابدأ من تقريب CMYK وأكّده مع مطبعتك: الشاشات والطابعات تعيد إنتاج اللون بشكل مختلف، فاختبار طباعة يستحق العناء.</p>\n<h2 id=\"building-a-full-palette\">كيف تبني لوحة كاملة من صورة</h2>\n<p>صورة واحدة تستطيع إعطاء لوحة كاملة: اختر لون الخلفية المهيمن ولون الموضوع الرئيسي وتمييزًا ونغمة داكنة للنص.</p>\n<p>أبقِ العدد منخفضًا: أربعة إلى ستة ألوان تكفي لمعظم التصاميم، وأكثر من ذلك غالبًا يجعل التصميم يبدو مبعثرًا. وراجع العينات معًا قبل التصدير: إذا كان لونان شبه متطابقين، تخلص من أحدهما. وإذا بدا المجموع غير متوازن، بدّل اختيارًا بدرجة أفتح أو أدكن.</p>\n<p>وعندما تريد عرض الصورة كاملة، جرّب <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصورة</a>: يرتب الألوان المهيمنة تلقائيًا، وهي طريقة سريعة للمقارنة مع مجموعتك المختارة يدويًا.</p>\n<h2 id=\"picking-from-charts\">كيف تأخذ ألوانًا من رسوم بيانية وتصورات بيانات</h2>\n<p>تستخدم الرسوم البيانية اللون لفصل سلاسل البيانات، ومطابقة تلك الألوان تهم عندما تبني تقريرًا أو لوحة بنفس البيانات: يستطيع المنتقي استرجاع كل لون سلسلة.</p>\n<p>عيّن وسط كل شريط أو خط أو قطاع دائرة، بعيدًا عن الحواف حيث تمتزج الألوان مع الخلفية: شريط سميك سهل العينة، بينما خط رفيع يحتاج عدسة. واعمل مع المفتاح أولًا، لأن المفتاح غالبًا يُظهر كل لون سلسلة ككتلة صلبة: تلك الكتل هي أنظف عينات في الرسم كله.</p>\n<p>وإذا بدا لونا سلسلة شبه متطابقين، راجع رمزي HEX قبل أن تقرر: ألوان تبدو متطابقة على الشاشة قد تختلف بما يكفي ليهم عندما تكون جنبًا إلى جنب. واحفظ ألوان السلاسل بالترتيب، بنفس ترتيب المفتاح: هكذا يحافظ رسمك الجديد على نفس تطابق اللون والسلسلة، والقراء الذين رأوا الأصل لا يرتبكون.</p>\n<p>وللوحات، خذ أيضًا ألوان الخلفية وخطوط الشبكة: لوحة تعيد استخدام الخلفية ونغمات الشبكة الأصلية تبدو مقصودة، بينما لوحة تستبدلها تبدو غير مترابطة.</p>\n<h2 id=\"saving-and-organizing\">كيف تحفظ وتنظم الألوان المختارة</h2>\n<p>الألوان المختارة تنفع فقط إذا استطعت إيجادها بعدها: تنزيل تصدير CSS هو أبسط طريقة لحفظ مجموعة، لأنه يحفظ كل عينة في ملف بأسماء متغيرات واضحة.</p>\n<p>سمِّ ملف التصدير حسب المشروع، لا حسب التاريخ: ملف اسمه colors-homepage-refresh.css مفيد بعد أشهر، بينما colors-2026-11-17.css لا يقول شيئًا عن المشروع. وإذا استخدمت أداة تصميم، الصق رموز HEX أيضًا في لوحة أنماطها أو متغيرات ألوانها: إبقاء نفس القيم في ورقة الأنماط وملف التصميم يمنعها من الانجراف.</p>\n<p>ولألوان العلامة، دوّن قيم RGB وCMYK بجانب رمز HEX في دليل علامتك: فرق مختلفة تحتاج صيغًا مختلفة، ودليل يسردها كلها يمنع التخمين. واحفظ ملاحظة قصيرة مع كل لوحة حول من أين جاءت الألوان: سطر مثل مأخوذ من صورة حملة الخريف يخبر مصممًا مستقبليًا لماذا تذهب هذه الألوان معًا.</p>\n<p>وأخيرًا، احتفظ بنسخة احتياطية من ملف CSS المصدّر مع بقية المشروع: لوحة تعيش فقط في تبويب متصفح تختفي لحظة إغلاق التبويب.</p>\n<h2 id=\"quick-reference-checklist\">قائمة مرجعية سريعة</h2>\n<p>ارفع أنظف ملف أصلي لديك، لا لقطة شاشة للقطة شاشة أخرى: كل حفظ إضافي قد يغيّر الألوان قليلًا.</p>\n<p>صوّب بالعدسة وعيّن وسط المناطق المسطحة وانقر بكسلين أو ثلاثة قريبين لتأكيد القيمة. وانسخ رمز HEX لعمل الويب والتصميم، وقيم RGB للمستندات، وتقريب CMYK لمهام الطباعة.</p>\n<p>صدّر CSS عندما تكون لديك أكثر من عينة وتحقق من اللون في مشروعك قبل البناء عليه. وللسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-muntqi-alwan-as-suwar/\">دليل منتقي ألوان الصورة الكامل</a> والمقارنة <a href=\"/ar/blog/hex-vs-rgb-vs-hsl/\">HEX مقابل RGB مقابل HSL: رموز الألوان موضحة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم لونًا يمكنني اختيارها من صورة؟","answer":"لا حد عملي لعدد العينات التي تستطيع جمعها في جلسة: اختر كل ما يحتاجه تصميمك، مع أن أربعة إلى ستة ألوان غالبًا تكفي للوحة متماسكة. والنقر مرتين على نفس قيمة HEX يترك عينة واحدة نظيفة."},{"question":"هل أحتاج تثبيت شيء لاختيار لون من صورة؟","answer":"لا، يعمل المنتقي بالكامل في متصفحك، في Chrome وSafari وFirefox وEdge. لا إضافة ولا ملحق ولا حساب: افتح صفحة الأداة وارفع صورتك وابدأ النقر."},{"question":"هل يمكنني اختيار لون من إطار فيديو أو فيديو متوقف؟","answer":"نعم، بشكل غير مباشر: أوقف الفيديو والتقط لقطة شاشة للإطار والصق اللقطة في المنتقي بـCtrl+V. وتقرأ الأداة بكسلات اللقطة مثل أي صورة أخرى، فتعمل الطريقة مع أي فيديو."},{"question":"لماذا تُظهر العدسة شبكة بدل الصورة العادية؟","answer":"تكبّر العدسة البكسلات حول مؤشرك لتستطيع رؤية كل منها منفصلًا: توضح الشبكة أي بكسل في الوسط وأيها بجانبه. وتلك الدقة هي ما يتيح لك تجنب بكسلات الحافة الممزوجة."},{"question":"أي صيغ صور تعمل مع منتقي الألوان؟","answer":"تعمل ملفات JPG وPNG وWebP وGIF، حتى 20 MB لكل ملف. وPNG هو الخيار الأفضل عندما تهم الدقة، لأنه يحفظ الألوان دون ضجيج ضغط. ويمكنك أيضًا لصق لقطات شاشة مباشرة."},{"question":"هل يمكنني اختيار ألوان من صورة على هاتفي؟","answer":"نعم، ارفع الصورة من معرضك والمس اللون الذي تريده: تساعدك العدسة على التصويب رغم حجم طرف الإصبع. ولألوان علامة حرجة، تحقق من القيمة الأخيرة بنقرة فأرة على حاسوب."}];
